package com.alpharip.staffmod.RecordingStudio.ui;
import com.alpharip.staffmod.RecordingStudio.core.RecordingStudioController;import com.alpharip.staffmod.RecordingStudio.integration.RecordingStudioRuntime;import net.minecraft.client.gui.*;import java.io.IOException;
/** Standalone Recording Studio screen for manual Minecraft recordings. */
public final class RecordingStudioScreen extends GuiScreen {
 private final RecordingStudioController controller;private final RecordingStudioRuntime runtime;private boolean navigating;
 public RecordingStudioScreen(RecordingStudioController c,RecordingStudioRuntime r){if(c==null||r==null)throw new IllegalArgumentException();controller=c;runtime=r;}
 public boolean doesGuiPauseGame(){return false;}
 public void initGui(){navigating=false;buttonList.clear();int x=width/2,y=height/2-100;buttonList.add(new GuiButton(0,x-125,y,120,20,"Start Recording"));buttonList.add(new GuiButton(1,x+5,y,120,20,"Pause"));buttonList.add(new GuiButton(2,x-125,y+25,120,20,"Resume"));buttonList.add(new GuiButton(3,x+5,y+25,120,20,"Stop"));buttonList.add(new GuiButton(4,x-125,y+58,120,20,"Timeline"));buttonList.add(new GuiButton(5,x+5,y+58,120,20,"Save Project"));buttonList.add(new GuiButton(6,x-125,y+88,250,20,"Camera Editor / View Camera"));buttonList.add(new GuiButton(7,x-125,y+113,120,20,"Interval - 100 ms"));buttonList.add(new GuiButton(8,x+5,y+113,120,20,"Interval + 100 ms"));buttonList.add(new GuiButton(9,x-125,y+143,120,20,"Start Audio"));buttonList.add(new GuiButton(10,x+5,y+143,120,20,"Stop Audio"));}
 protected void actionPerformed(GuiButton b)throws IOException{switch(b.id){case 0:controller.start();break;case 1:controller.pause();break;case 2:controller.resume();break;case 3:controller.stop();break;case 4:navigating=true;mc.displayGuiScreen(new TimelineEditorScreen(this,controller.getTimeline()));break;case 5:controller.save();break;case 6:navigating=true;mc.displayGuiScreen(new CameraEditorScreen(this,runtime.getCameraController(),mc.mcDataDir));break;case 7:controller.adjustCaptureInterval(-100L);break;case 8:controller.adjustCaptureInterval(100L);break;case 9:controller.startAudioCapture();break;case 10:controller.stopAudioCapture();break;default:break;}}
 protected void keyTyped(char c,int k)throws IOException{if(k==1){mc.displayGuiScreen(null);return;}super.keyTyped(c,k);}
 public void onGuiClosed(){if(!navigating)runtime.shutdown();}
 public void drawScreen(int mx,int my,float pt){drawDefaultBackground();drawCenteredString(fontRendererObj,"RECORDING STUDIO",width/2,24,0xFFC83D);drawCenteredString(fontRendererObj,controller.getProject().getName(),width/2,42,0xFFFFFF);drawCenteredString(fontRendererObj,"Status: "+controller.getStatus(),width/2,height/2+115,0xBBBBBB);drawCenteredString(fontRendererObj,"Frames saved: "+controller.getCapture().getFrameCount()+" | Pending: "+controller.getCapture().getPendingFrameCount()+" | Failed: "+controller.getCapture().getFailedFrameCount(),width/2,height/2+129,0xBBBBBB);drawCenteredString(fontRendererObj,"Timeline duration: "+controller.getTimeline().duration()+" ms | Capture interval: "+controller.getCapture().getIntervalMillis()+" ms",width/2,height/2+143,0xBBBBBB);drawCenteredString(fontRendererObj,controller.getAudioStatus(),width/2,height/2+157,0xBBBBBB);super.drawScreen(mx,my,pt);}
}
